package it;

import java.nio.file.*;
import java.security.KeyStore;

import javax.net.ssl.*;

import com.king.gmms.client.SslSmppClient;
import com.king.gmms.messagequeue.StreamQueueManager;
import com.king.message.gmms.GmmsMessage;

/** The real SslSmppClient against a TLS vendor: certificate generated by keytool, Ssl.IsClientTrustAll. */
public class ClientTlsIT extends ItSupport {
	static final int PORT = 17798;

	public static void main(String[] args) throws Exception {
		home = System.getProperty("a2p_home");
		String ks = home + "conf/it-ks.jks";
		new ProcessBuilder(System.getProperty("java.home") + "/bin/keytool", "-genkeypair", "-alias", "a2p", "-keyalg", "RSA", "-keysize", "2048", "-validity", "30", "-dname", "CN=localhost", "-keystore", ks, "-storepass", "tomcata2p", "-keypass", "tomcata2p", "-storetype", "JKS").inheritIO().start().waitFor();
		Path cfg = Paths.get(home + "Gmms/GmmsConfig.properties");
		Files.write(cfg, (new String(Files.readAllBytes(cfg), "UTF-8") + "\nSsl.KeyStorePath=" + ks + "\nSsl.TrustStorePath=" + ks + "\nSsl.IsClientTrustAll=true\n").getBytes("UTF-8"));
		Path p = Paths.get(home + "conf/cm.cfg");
		Files.write(p, (new String(Files.readAllBytes(p), "UTF-8") + "\n[TV901]\nCCBSSID: 901\nA2PPlayerType: operator\nProtocol: SSLSMPP\nConnectionType: MC\nIsInit: true\nReconnectInterval: 1\nEnquireLink: false\nWindowSize: 50\nBufferTimeout: 30\n"
				+ "OutgoingConnection: (ConnName=TV901_c1,userName=u901,password=p,URL=127.0.0.1,Port=" + PORT + ",SessionNumber=1,BindMode=TRX,Version=V34,IsInit=true)\n").getBytes("UTF-8"));
		KeyStore store = KeyStore.getInstance("JKS");
		try (java.io.InputStream in = Files.newInputStream(Paths.get(ks))) { store.load(in, "tomcata2p".toCharArray()); }
		KeyManagerFactory kmf = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
		kmf.init(store, "tomcata2p".toCharArray());
		SSLContext ctx = SSLContext.getInstance("TLS");
		ctx.init(kmf.getKeyManagers(), null, null);
		FakeSmsc smsc = new FakeSmsc(ctx.getServerSocketFactory().createServerSocket(PORT));
		FakeSmsc.Account a = smsc.account("u901");
		try {
			boot();
			new SslSmppClient().startService();
			check(waitFor(() -> a.binds.get() == 1, 15000), "CN-14a TLS channel: handshake and bind");
			Thread.sleep(300);
			GmmsMessage m = mt("8888_TL1", 8888, 901, 0);
			m.setTextContent("8888_TL1");
			m.setMessageSize(8);
			StreamQueueManager.getInstance().produceOutboundMessage(m);
			waitFor(() -> !inStreams("stream:core:results*", "8888_TL1").isEmpty(), 8000);
			java.util.List<GmmsMessage> r = inStreams("stream:core:results*", "8888_TL1");
			System.out.println("INFO result " + (r.isEmpty() ? "none" : r.get(0).getStatusCode() + " " + r.get(0).getStatusText()) + ", at the vendor " + a.count("8888_TL1"));
			check(a.count("8888_TL1") == 1, "CN-14b MT reaches the vendor over TLS");
			check(!r.isEmpty() && r.get(0).getStatusCode() == 0, "CN-14c success result: " + (r.isEmpty() ? "none" : r.get(0).getStatusCode()));
			a.closeAll();
			check(waitFor(() -> a.binds.get() == 2, 10000), "CN-14d connection lost: reconnects with TLS");
		} catch (Throwable x) { x.printStackTrace(System.out); failures++; }
		exit();
	}
}
